effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    #define S smoothstep
    // #define T (iTime * 0.5)

    mat2 Rot(float a)
    {
        float s = sin(a), c = cos(a);
        return mat2(c, -s, s, c);
    }

    float Feather(vec2 uv)
    {
        // Vec2 offsets the center, x, y coordinates on the screen
       	float d = length(uv - vec2(0, clamp(uv.y,-0.3, 0.3)));

        float r = mix(0.1, 0.01, S(-0.3, THICKNESS, uv.y));
        float m = S(0.01, 0.0, d - r);


        // Returns the value of the sign of uv.x, 0 is the center of the screen,
        // -1 when negative, +1 when positive
        float side = sign(uv.x);

        float x = 0.9 * abs(uv.x) / r;
        float wave = (DENSITY -x) * sqrt(x) + (DIRECTION - sqrt(BRANCH - x)) * x;
        float y = (uv.y - wave * 0.2) * 80.0 + side;
        // float wave = (1.0 -x) * sqrt(x) + (1.0 - sqrt(1.0 - x)) * x;            

        float id = floor(y + 20.0);
        float n = fract(sin(id * 650.2) * 795.0); // semi-random number between 0 - 1
        float shade = mix(SHADELENGTH, 1.0, n);
        float strandLength = mix(SMOOTHLESS, 1.0, fract(n * 2.0));

        // fract creates repetition.
        float strand = S(0.6, 0.0, abs(fract(y) - 0.5) - 0.3);
        strand *= S(0.3, 0.0, x - strandLength);

        d = length(uv - vec2(0, clamp(uv.y,-0.45, 0.2)));
    	float stem = S(0.01, 0.0, d + uv.y * 0.02);

        // Taking the max of 2 values is better as it will not have hidden information
        return max(strand*m*shade, stem);
    }

    vec3 Transform(vec3 p, float angle)
    {
        p.xz *= Rot(angle);
        p.xy *= Rot(angle * ROTFEATHER);
        // p.xy *= Rot(angle *0.7);
        return p;
    }

    vec4 RayTracedFeather(vec3 rayOrigin, vec3 rayDirection, vec3 position, float angle)
    {

        vec4 col = vec4(0);
        float t = dot(position - rayOrigin, rayDirection);
        vec3 p = rayOrigin + rayDirection * t;

        float y = length(position - p);

        // Ray traced sphere
        if (y < 1.0)
        {
        	float x = sqrt(1.0 - y);
            vec3 pF = rayOrigin + rayDirection * (t - x) - position; // Front intersection

            pF = Transform(pF, angle);
            // Cylindrical projection using polar coordinates.
            vec2 uvF = vec2(atan(pF.x, pF.z), pF.y); // -pi to pi, -1 to 1;
            uvF *= vec2(0.25, 0.5);
            float f = Feather(uvF);
            vec4 front = vec4(vec3(f), S(0.0, 0.1, f));

            vec3 pB = rayOrigin + rayDirection * (t + x) - position; // Back intersection
            pB = Transform(pB, angle);
            vec2 uvB = vec2(atan(pB.x, pB.z), pB.y); // -pi to pi, -1 to 1;
            uvB *= vec2(0.25, 0.5);
            float b = Feather(uvB);
            vec4 back = vec4(vec3(b), S(0.0, 0.1, b));

            col = mix(back, front, front.a);
        }

        return col;
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float T = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 TanRyu;
    // TanRyu = acScreenNorm; 
    TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    TanRyu.y*=acLayerSize.y/acLayerSize.x;

    TanRyu /= scale;
    TanRyu *= rot2m((0.0+angle)*0.0174533);
    TanRyu += vec2((0.0+position.x), (0.0-position.y))*vec2(-1.0,1.0)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    TanRyu /= scaleVec;

    /////////////////////////

	vec4 fragColor;

        vec2 uv = TanRyu;
        vec2 M = iMouse.xy / iResolution.xy;

        vec3 bg = vec3(0.0, 0.0, 0.0);
        vec4 col = vec4(bg, 0);

        // ray tracer
        vec3 rayOrigin = vec3((RAYORIGIN.x*0.01), (RAYORIGIN.y*0.01), (RAYORIGIN.z*0.01));
        // vec3 rayOrigin = vec3(0, 0, -3);
        vec3 rayDir = normalize(vec3(uv, 1));

        for(float i= 0.0; i < 1.0; i+= 1.0/AMOUNT)
        // for(float i= 0.0; i < 1.0; i+= 1.0/51.0)
        {
            float x = mix(-8.0 , 8.0, fract(i + T*0.1)) + M.x * i * i;
            float y = mix(-2.0, 2.0,fract(sin(i * 324.5) * 7864.4)) + (M.y * i*i);
            float z = mix(5.0, 0.0, i);
            float a = T + i *530.35;
            vec4 feather = RayTracedFeather(rayOrigin, rayDir, vec3(x, y, z), a);

            feather.rg *= i;
            feather.b += i;
            feather.rgb = mix(bg.rgb, feather.rgb, mix(0.3, 1.0, i));
            feather.rgb = sqrt(feather.rgb);
            col = mix(col, feather, feather.a);
        }

        col = pow(col, vec4(0.4545)); // gamma correction
        fragColor = col;

	    vec4 factor = mix(texColorX,fragColor,1.0);

	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
	    if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.0)*(1.-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }
      else if( blendMode==3 ) { factor *= hardness; resultfinal = newLayer(texColor, (factor*hardness)) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
